public static int maxStack(Stack<Integer> s) {
    Stack<Integer> temp = new Stack<Integer>();
    int max = s.top();
    while (!s.isEmpty()) {
        int x = s.pop();
        if (x > max) {
            max = x;
        }
        temp.push(x);
    }
    // מחזירים את האיברים — המחסנית חוזרת להיות כמו בהתחלה
    while (!temp.isEmpty()) {
        s.push(temp.pop());
    }
    return max;
}

public static boolean contains(Stack<Integer> s, int x) {
    Stack<Integer> temp = new Stack<Integer>();
    boolean found = false;
    while (!s.isEmpty()) {
        int y = s.pop();
        if (y == x) {
            found = true;
        }
        temp.push(y);
    }
    // מחזירים את האיברים — המחסנית חוזרת להיות כמו בהתחלה
    while (!temp.isEmpty()) {
        s.push(temp.pop());
    }
    return found;
}

